// =============================================================================
// Stage 4B — Prepare Audit Input
// =============================================================================
//
// Purpose:
// Receive the complete Stage 4B call packet from the parent workflow
// and normalize it into a clean audit payload.
//
// Stage 4B audits only.
// It does NOT rewrite the proposal.
// =============================================================================

const input = $json;

// -----------------------------------------------------------------------------
// Helpers
// -----------------------------------------------------------------------------

function isObject(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function cleanString(value) {
  return typeof value === "string"
    ? value.trim()
    : "";
}

function cleanStringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter(item => typeof item === "string")
    .map(item => item.trim())
    .filter(Boolean);
}

function requireObject(value, fieldName) {
  if (!isObject(value)) {
    throw new Error(
      `Missing or invalid required object: ${fieldName}`
    );
  }

  return value;
}

function normalizeProposal(value) {
  const proposal = requireObject(
    value,
    "stage4a_output.proposal"
  );

  const fullText = cleanString(
    proposal.full_text
  );

  if (!fullText) {
    throw new Error(
      "Stage 4A proposal.full_text is missing or empty."
    );
  }

  return {
    opening:
      cleanString(proposal.opening),

    capabilities:
      cleanString(proposal.capabilities),

    project_examples:
      cleanString(proposal.project_examples),

    engineering_approach:
      cleanString(proposal.engineering_approach),

    clarifying_questions:
      cleanStringArray(
        proposal.clarifying_questions
      ),

    risks_and_limitations:
      cleanString(
        proposal.risks_and_limitations
      ),

    closing_cta:
      cleanString(proposal.closing_cta),

    full_text:
      fullText
  };
}

// -----------------------------------------------------------------------------
// Validate parent workflow packet
// -----------------------------------------------------------------------------

if (
  input.routing?.block_stage_4b === true
) {
  throw new Error(
    "Stage 4B was explicitly blocked by the parent workflow."
  );
}

const jobId =
  cleanString(input.job_id);

if (!jobId) {
  throw new Error(
    "Stage 4B received no job_id."
  );
}

const stage4AOutput =
  requireObject(
    input.stage4a_output,
    "stage4a_output"
  );

const proposal =
  normalizeProposal(
    stage4AOutput.proposal
  );

const writingBrief =
  requireObject(
    input.writing_brief,
    "writing_brief"
  );

const executionContract =
  requireObject(
    input.approved_execution_contract,
    "approved_execution_contract"
  );

const safetyContract =
  requireObject(
    input.safety_contract,
    "safety_contract"
  );

// -----------------------------------------------------------------------------
// Optional context
// -----------------------------------------------------------------------------

const verifiedEvidence =
  isObject(input.verified_evidence)
    ? input.verified_evidence
    : {};

const jobContext =
  isObject(input.job_context)
    ? input.job_context
    : {};

const proposalStrategy =
  isObject(input.proposal_strategy)
    ? input.proposal_strategy
    : {};

// -----------------------------------------------------------------------------
// Contract checks
// -----------------------------------------------------------------------------

if (
  !Array.isArray(
    executionContract.must_mention
  )
) {
  throw new Error(
    "approved_execution_contract.must_mention is missing."
  );
}

if (
  !Array.isArray(
    executionContract.proposal_structure
  )
) {
  throw new Error(
    "approved_execution_contract.proposal_structure is missing."
  );
}

if (
  !Array.isArray(
    executionContract.projects
  )
) {
  throw new Error(
    "approved_execution_contract.projects is missing."
  );
}

if (
  !Array.isArray(
    executionContract.nice_to_mention
  )
) {
  throw new Error(
    "approved_execution_contract.nice_to_mention is missing."
  );
}

if (
  !Array.isArray(
    executionContract.client_concerns
  )
) {
  throw new Error(
    "approved_execution_contract.client_concerns is missing."
  );
}

// -----------------------------------------------------------------------------
// Build clean Stage 4B audit input
// -----------------------------------------------------------------------------

const auditInput = {
  stage4b_input_version: "1.1.0",

  audit_mode:
    "proposal_contract_audit",

  job_id:
    jobId,

  proposal_to_audit:
    proposal,

  job_context:
    jobContext,

  writing_brief:
    writingBrief,

  approved_execution_contract:
    executionContract,

  safety_contract:
    safetyContract,

  verified_evidence:
    verifiedEvidence,

  proposal_strategy:
    proposalStrategy,

  audit_scope: {
    must_mention:
      executionContract.must_mention,

    proposal_structure:
      executionContract.proposal_structure,

    projects:
      executionContract.projects,

    nice_to_mention:
      executionContract.nice_to_mention,

    client_concerns:
      executionContract.client_concerns,

    positioning:
      executionContract.positioning ?? {},

    story:
      executionContract.story ?? {},

    cta:
      executionContract.cta ?? {},

    tone:
      executionContract.tone ?? {}
  },

  audit_rules: {
    audit_only: true,

    never_rewrite_proposal: true,

    compare_semantically:
      true,

    preserve_every_contract_id:
      true,

    audit_every_must_mention:
      true,

    audit_every_proposal_structure_item:
      true,

    audit_every_project:
      true,

    audit_every_nice_to_mention_item:
      true,

    audit_every_client_concern:
      true,

    distinguish_required_from_optional:
      true,

    required_items_must_not_disappear:
      true,

    optional_items_may_be_omitted:
      true,

    used_requires_real_proposal_excerpt:
      true,

    omitted_requires_reason:
      true,

    detect_unsupported_claims:
      true,

    detect_safety_violations:
      true,

    detect_honesty_boundary_violations:
      true,

    detect_budget_contradictions:
      true,

    detect_scope_contradictions:
      true,

    detect_internal_language:
      true,

    detect_placeholders:
      true,

    detect_generic_filler:
      true,

    output_valid_json_only:
      true
  }
};

// -----------------------------------------------------------------------------
// Return
// -----------------------------------------------------------------------------

return [
  {
    json: auditInput
  }
];
